<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { enterpriseInternshipApi } from '../services/enterpriseInternshipApi'
import { useEnterpriseContextStore } from '../stores/enterpriseContext'
const route=useRoute(),router=useRouter(),context=useEnterpriseContextStore(),id=computed(()=>route.params.id),loading=ref(Boolean(route.params.id)),saving=ref(false),error=ref('')
const form=reactive({name:'',category:'',headcount:null,city:'',work_address:'',major_requirement:'',grade_requirement:'',mentor_contact_id:null,work_content:'',requirement_note:'',daily_hours:null,weekly_hours:null,shift_type:'DAY',night_shift:false,overtime_allowed:false,rest_days_per_week:null,pay_type:'MONTHLY',pay_amount:null,pay_period:'MONTHLY',salary_display:'',subsidy:'',accommodation:'',meals:'',hazardous:false,special_equipment:'',prohibited_arrangement_note:''})
const checks=computed(()=>[{ok:Boolean(form.name),text:'岗位名称已填写'},{ok:Number(form.headcount)>0,text:'招聘人数已填写'},{ok:Boolean(form.work_content),text:'工作内容已填写'},{ok:Number(form.weekly_hours)>0,text:'每周工时已填写'},{ok:Boolean(form.salary_display||form.pay_amount),text:'报酬条件完整'},{ok:!form.night_shift,text:form.night_shift?'夜班岗位需学校进一步核验':'无夜班特殊核验'}])
onMounted(async()=>{if(!id.value)return;try{Object.assign(form,await enterpriseInternshipApi.position(id.value)||{})}catch(e){error.value=e.message||'岗位加载失败'}finally{loading.value=false}})
async function save(submit=false){if(!context.recruitmentWritable){error.value='招聘季已关闭或 RECRUITMENT Grant 不可写，岗位仅可历史查看';return}saving.value=true;error.value='';try{let pid=id.value;if(pid) await enterpriseInternshipApi.updatePosition(pid,{...form});else{const created=await enterpriseInternshipApi.createPosition({...form});pid=created?.id}if(submit){if(!pid)throw new Error('岗位保存后未返回 canonical id');await enterpriseInternshipApi.submitPosition(pid)}await router.push('/positions')}catch(e){error.value=e.message||'岗位保存失败'}finally{saving.value=false}}
</script>
<template><section class="ep-page"><div class="ep-page-head"><div><h1 class="ep-title">{{ id?'编辑岗位':'创建实习岗位' }}</h1><p class="ep-subtitle">保存草稿允许未完整；提交后进入学校审核，企业端没有“直接发布”。</p></div></div><div v-if="!context.recruitmentWritable" class="history-note">当前招聘季不可写：页面保留历史字段查看，保存/提交动作已禁用。</div><div v-if="error" class="ep-error">{{ error }}</div><div v-if="loading" class="ep-card ep-empty">正在加载岗位…</div><div v-else class="form-layout"><div class="sections"><section class="ep-card panel"><h2>1. 基本信息</h2><div class="fields"><label>岗位名称 *<input v-model="form.name" class="ep-input" :disabled="!context.recruitmentWritable"></label><label>岗位类别<input v-model="form.category" class="ep-input" :disabled="!context.recruitmentWritable"></label><label>招聘人数 *<input v-model.number="form.headcount" type="number" min="1" class="ep-input" :disabled="!context.recruitmentWritable"></label><label>工作城市 *<input v-model="form.city" class="ep-input" :disabled="!context.recruitmentWritable"></label><label class="wide">工作地点 *<input v-model="form.work_address" class="ep-input" :disabled="!context.recruitmentWritable"></label><label>专业要求<input v-model="form.major_requirement" class="ep-input" :disabled="!context.recruitmentWritable"></label><label>年级要求<input v-model="form.grade_requirement" class="ep-input" :disabled="!context.recruitmentWritable"></label></div></section><section class="ep-card panel"><h2>2. 岗位职责 / 要求</h2><label>工作内容 *<textarea v-model="form.work_content" class="ep-textarea" rows="6" :disabled="!context.recruitmentWritable" /></label><label>补充要求<textarea v-model="form.requirement_note" class="ep-textarea" rows="3" :disabled="!context.recruitmentWritable" /></label></section><section class="ep-card panel"><h2>3. 工作安排</h2><div class="fields"><label>每日工时 *<input v-model.number="form.daily_hours" type="number" class="ep-input" :disabled="!context.recruitmentWritable"></label><label>每周工时 *<input v-model.number="form.weekly_hours" type="number" class="ep-input" :disabled="!context.recruitmentWritable"></label><label>班次<select v-model="form.shift_type" class="ep-select" :disabled="!context.recruitmentWritable"><option>DAY</option><option>ROTATING</option></select></label><label>每周休息天数 *<input v-model.number="form.rest_days_per_week" type="number" class="ep-input" :disabled="!context.recruitmentWritable"></label><label class="check"><input v-model="form.night_shift" type="checkbox" :disabled="!context.recruitmentWritable">存在夜班</label><label class="check"><input v-model="form.overtime_allowed" type="checkbox" :disabled="!context.recruitmentWritable">允许加班</label></div></section><section class="ep-card panel"><h2>4. 薪酬福利</h2><div class="fields"><label>报酬类型<select v-model="form.pay_type" class="ep-select" :disabled="!context.recruitmentWritable"><option>MONTHLY</option><option>DAILY</option><option>HOURLY</option></select></label><label>报酬金额<input v-model.number="form.pay_amount" type="number" class="ep-input" :disabled="!context.recruitmentWritable"></label><label>薪资展示<input v-model="form.salary_display" class="ep-input" placeholder="如 3500-4500/月" :disabled="!context.recruitmentWritable"></label><label>补贴<input v-model="form.subsidy" class="ep-input" :disabled="!context.recruitmentWritable"></label><label>住宿<input v-model="form.accommodation" class="ep-input" :disabled="!context.recruitmentWritable"></label><label>餐食<input v-model="form.meals" class="ep-input" :disabled="!context.recruitmentWritable"></label></div></section><section class="ep-card panel"><h2>5. 安全权益</h2><label class="check"><input v-model="form.hazardous" type="checkbox" :disabled="!context.recruitmentWritable">危险/特殊岗位</label><label>特殊设备<input v-model="form.special_equipment" class="ep-input" :disabled="!context.recruitmentWritable"></label><label>禁止安排说明<textarea v-model="form.prohibited_arrangement_note" class="ep-textarea" rows="3" :disabled="!context.recruitmentWritable" /></label></section></div><aside class="ep-card preview"><h2 class="ep-section-title">学校发布检查预览</h2><div v-for="check in checks" :key="check.text" class="check-row" :class="check.ok?'ok':'warn'">{{ check.ok?'✓':'!' }} {{ check.text }}</div><p class="ep-muted">这里只做前端预检查；是否可发布仍由学校 canonical rights gate 决定。</p></aside></div><div class="actions"><button class="ep-btn" :disabled="saving||!context.recruitmentWritable" @click="save(false)">保存草稿</button><button class="ep-btn ep-btn-primary" :disabled="saving||!context.recruitmentWritable" @click="save(true)">提交学校审核</button></div></section></template>
<style scoped>.history-note{padding:12px 14px;margin-bottom:14px;background:var(--warn-bg);color:var(--warn-fg);border-radius:8px;font-size:13px}.form-layout{display:grid;grid-template-columns:minmax(0,1fr) 310px;gap:16px;align-items:start}.sections{display:grid;gap:14px}.panel,.preview{padding:20px}.panel h2{font-size:16px;margin:0 0 16px}.fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}label{display:flex;flex-direction:column;gap:7px;font-size:13px;color:var(--t2);margin-bottom:13px}.fields label{margin-bottom:0}.wide{grid-column:1/-1}.check{flex-direction:row;align-items:center;min-height:40px}.ep-input,.ep-select,.ep-textarea{width:100%}.preview{position:sticky;top:78px}.check-row{padding:9px 0;border-bottom:1px solid var(--line);font-size:13px}.check-row.ok{color:var(--ok-fg)}.check-row.warn{color:var(--warn-fg)}.actions{display:flex;justify-content:flex-end;gap:10px;position:sticky;bottom:0;background:linear-gradient(transparent,var(--page) 30%);padding:24px 0 6px}@media(max-width:1000px){.form-layout{grid-template-columns:1fr}.preview{position:static}}@media(max-width:700px){.fields{grid-template-columns:1fr}.wide{grid-column:auto}}</style>
